\label{problem:LTS}
   Find the LTS estimate
   \begin{equation} \label{eq:OF_LTS_def_problem}
       \hat{\beta = \argmin_{\beta \in \mathbb{R^{p}} \sum_{i=1
       \res{i}(\beta) = \argmin_{\beta \in \mathbb{R^{p}} \sum_{i=1 (y_i - \beta
       x_i^T)^2,
   \end{equation}
   where $n > p \geq 1$, $Y = (y_1, \ldots, y_n)^T$, $X = (x_1, \ldots, x_n)^T$ is a matrix from
    $\mathbb{R^{n,p}$, and $h$ is an integer such that $p \leq h \leq n$.

   Further, let us denote the data for which the problem is defined by
   \begin{equation*}
       \mathcal{D = \{(y_i,x_i^T)\,|\,i \in \hat{n\}.
   \end{equation*}

 \label{def:relation_Z}
We define a~relation $Z \subset \mathbb{R^{p} \times Q^{(n,h)$ by
\begin{equation*}
    (\beta,w) \in Z \Leftrightarrow \sum_{i=1 \res{i}(\beta) = \sum_{i=1
    w^i r_i^2 (\beta).
\end{equation*}
Further, we define a set $\mathcal{U \subset \mathbb{R^p$ as the set where $Z$
is a mapping from $\mathbb{R^p$ to $Q^{(n,h)$. Complement of $\mathcal{U$ to $\mathbb{R^p$
is denoted by $\mathcal{H$.

\label{def:sequence_Ui}
   For \PLTS\ we define a sequence of $m \in \mathbb{N$ sets $\mathcal{U =
   \{U_i\}_{i=1}^m$ such that
   \begin{enumerate}
       \item $U_i$ is open and connected\footnote{By definition, an open set $A$ is connected if it cannot be represented as the disjoint union of two or more nonempty open sets.}, for all $i = 1, \ldots, m$,
       \item $U_i \cap U_j = \emptyset$, for all $i,j, i \neq j$,
       \item $\cup_{i=1}^m U_i = \mathcal{U$,
       \item $\cup_{i=1}^m \partial U_i = \mathcal{H$.
   \end{enumerate}
   We say that $U_i, U_j \in \mathcal{U$ are \emph{neighbours} if $i \neq
   j$ and $\partial U_i \cap \partial U_j \neq \emptyset$.
   Further, we define a set $W^{(\text{min$ of $m$ vectors from $Q^{(n,h)$
   \begin{equation*}
       W^{(\text{min = \{w_1,\ldots, w_m \,|\,  w_i = Z(\beta),\text{ where } \beta \in
       U_i, i \in \hat{m\}.
   \end{equation*}

