    Then we define an order of $\beta$
    \begin{equation*}
       \mathrm{Ord}(\beta) = \textrm{ number of linearly independent equations in \eqref{eq:equations}}.
    \end{equation*}
    We also define a set of \emph{zero-dimensional intersections}
    \begin{equation*}
       H_p = \{ \beta \in H\,|\,\mathrm{Ord}(\beta) = p \}
    \end{equation*}
    and its subset $\mathcal{H_p$ of such $\beta \in H_p$ for which $r^2_{i_1}(\beta) = \ldots = r_{i_{p+1}}^2(\beta) =
    \res{h}(\beta) = \res{h+1}(\beta)$, where $i_1, \ldots, i_{p+1} \in \hat{n$ are indices
    from the system of $p$ linearly independent equations of type \eqref{eq:equations}.

\proof \\
Assumption \ref{assump:hth_residual} implies that for all $s,t \in \hat{n,
s \neq t$ the system
\begin{equation} \label{eq:lemma_pre_GAMFOG}
    \begin{split}
    (x_s + x_t)^T \beta & = y_s + y_t\\
    (x_s - x_t)^T \beta & = y_s - y_t
    \end{split}
\end{equation}
has not any solution $\beta \in \mathbb{R{p}$ such that $r_s^2(\beta) =
r_t^2(\beta) = \res{h}(\beta)$. Indeed, if $\beta_0$ is a~solution
of both equations~\eqref{eq:lemma_pre_GAMFOG} and $r_s^2(\beta) =
r_t^2(\beta) = \res{h}(\beta)$,  then $r_s(\beta_0) =
r_t(\beta_0)$ and simultaneously $r_s(\beta_0) = - r_t(\beta_0)$
and so $\res{h}(\beta_0) = 0$, i.e. Assumption
\ref{assump:hth_residual} is not fulfilled (if $r_{(h)}(\beta_0) =
0$ then certainly $\beta_0 = \hat{\beta$).

Now, let us assume, without loss to generality, that $j < k$ holds
for $j,k$. Then for any $\beta \in B$
\begin{equation*}
    \begin{split}
